   Let's write the CSV conversion function carefully:
   ```cpp
   bool convertXlsxToCsv(const QString& xlsxPath, const QString& csvPath) {
       QXlsx::Document xlsxDoc(xlsxPath);
       if (!xlsxDoc.load()) return false;

       // Get first sheet
       xlsxDoc.selectSheet(1); // or xlsxDoc.sheetNames().first()
       QXlsx::CellRange range = xlsxDoc.dimension();
       if (!range.isValid()) {
           // Empty sheet, create empty CSV
           QFile f(csvPath);
           return f.open(QIODevice::WriteOnly);
       }

       QFile csvFile(csvPath);
       if (!csvFile.open(QIODevice::WriteOnly | QIODevice::Text)) return false;
       QTextStream out(&csvFile);
       out.setCodec("UTF-8");

       for (int row = range.firstRow(); row <= range.lastRow(); ++row) {
           QStringList line;
           for (int col = range.firstColumn(); col <= range.lastColumn(); ++col) {
               QXlsx::Cell* cell = xlsxDoc.cellAt(row, col);
               QString val = cell ? cell->value().toString() : "";
               // CSV escape
               if (val.contains(',') || val.contains('"') || val.contains('\n')) {
                   val.replace('"', "\"\"");
                   val = "\"" + val + "\"";
               }
               line << val;
           }
           out << line.join(',') << "\n";
       }
       csvFile.close();
       return true;
   }
   ```

   Wait, QXlsx API: `xlsxDoc.selectSheet()` might not work exactly like that. Let me check QXlsx documentation mentally:
