       void startConversion() {
           if (selectedDir.isEmpty()) return;

           QDir dir(selectedDir);
           QStringList filters = {"*.xlsx"}; // QXlsx only supports .xlsx
           QStringList excelFiles = dir.entryList(filters, QDir::Files);

           if (excelFiles.isEmpty()) {
               QMessageBox::information(this, "Info", "No .xlsx files found in the selected directory.");
               return;
           }

           QString outputDir = selectedDir + "/csv_output";
           if (!dir.mkpath(outputDir)) {
               QMessageBox::critical(this, "Error", "Failed to create output directory.");
               return;
           }

           progressBar->setRange(0, excelFiles.size());
           progressBar->setValue(0);
           statusLabel->setText("Converting...");
           convertBtn->setEnabled(false);

           int successCount = 0;
           for (int i = 0; i < excelFiles.size(); ++i) {
               QString xlsxPath = dir.absoluteFilePath(excelFiles[i]);
               QString baseName = QFileInfo(excelFiles[i]).completeBaseName();
               QString csvPath = outputDir + "/" + baseName + ".csv";

               if (convertXlsxToCsv(xlsxPath, csvPath)) {
                   successCount++;
               } else {
                   statusLabel->setText("Failed: " + excelFiles[i]);
               }
               progressBar->setValue(i + 1);
               QApplication::processEvents();
           }

           statusLabel->setText(QString("Done! %1/%2 files converted.").arg(successCount).arg(excelFiles.size()));
           convertBtn->setEnabled(true);
           QMessageBox::information(this, "Complete", QString("Converted %1 files to:\n%2").arg(successCount).arg(outputDir));
       }

   private:
       bool convertXlsxToCsv(const QString& xlsxPath, const QString& csvPath) {
           QXlsx::Document doc(xlsxPath);
           if (!doc.load()) return false;

           QStringList sheets = doc.sheetNames();
           if (sheets.isEmpty()) return false;

           doc.selectSheet(sheets.first());
           QXlsx::CellRange range = doc.dimension();
           if (!range.isValid()) {
               QFile f(csvPath);
               return f.open(QIODevice::WriteOnly);
           }

           QFile csvFile(csvPath);
           if (!csvFile.open(QIODevice::WriteOnly | QIODevice::Text)) return false;
           QTextStream out(&csvFile);
           out.setCodec("UTF-8");

           for (int row = range.firstRow(); row <= range.lastRow(); ++row) {
               QStringList line;
               for (int col = range.firstColumn(); col <= range.lastColumn(); ++col) {
                   QXlsx::Cell* cell = doc.cellAt(row, col);
                   QString val = cell ? cell->value().toString() : "";
                   if (val.contains(',') || val.contains('"') || val.contains('\n') || val.contains('\r')) {
                       val.replace('"', "\"\"");
                       val = "\"" + val + "\"";
                   }
                   line << val;
               }
               out << line.join(',') << "\n";
           }
           csvFile.close();
           return true;
       }

       void setupUi() {
           QVBoxLayout* layout = new QVBoxLayout(this);
           selectBtn = new QPushButton("Select Directory", this);
           convertBtn = new QPushButton("Convert to CSV", this);
           dirLabel = new QLabel("No directory selected", this);
           statusLabel = new QLabel("Ready", this);
           progressBar = new QProgressBar(this);
           progressBar->setValue(0);

           layout->addWidget(selectBtn);
           layout->addWidget(convertBtn);
           layout->addWidget(dirLabel);
           layout->addWidget(progressBar);
           layout->addWidget(statusLabel);
           layout->addStretch();
           setLayout(layout);
           setWindowTitle("Excel to CSV Converter");
           resize(400, 250);
       }

       QPushButton* selectBtn;
       QPushButton* convertBtn;
       QLabel* dirLabel;
       QLabel* statusLabel;
       QProgressBar* progressBar;
       QString selectedDir;
   };

   #include "main.moc" // For single-file compilation

   int main(int argc, char* argv[]) {
       QApplication app(argc, argv);
       ExcelToCsvConverter converter;
       converter.show();
       return app.exec();
   }
   ```

