Here's a complete, working Qt5 example. Since Qt doesn't include native Excel parsing, this solution uses **QXlsx** (the modern, maintained Qt Excel library) to read `.xlsx` files and write properly escaped CSVs.

### 🔧 Prerequisites
You'll need to add QXlsx to your project. The easiest way is via CMake:
```bash
# Clone QXlsx somewhere in your project or system
git clone https://github.com/QtExcel/QXlsx.git
```

### 📦 CMakeLists.txt
```cmake
cmake_minimum_required(VERSION 3.16)
project(ExcelToCsvConverter LANGUAGES CXX)

set(CMAKE_CXX_STANDARD 17)
set(CMAKE_CXX_STANDARD_REQUIRED ON)
set(CMAKE_AUTOMOC ON)
set(CMAKE_AUTORCC ON)
set(CMAKE_AUTOUIC ON)

find_package(Qt5 REQUIRED COMPONENTS Widgets Concurrent)

# Add QXlsx (adjust path to where you cloned it)
add_subdirectory(QXlsx QXlsxBuild)

add_executable(${PROJECT_NAME} main.cpp)
target_link_libraries(${PROJECT_NAME} PRIVATE Qt5::Widgets Qt5::Concurrent QXlsx::QXlsx)
```

### 💻 main.cpp
```cpp
#include <QApplication>
#include <QWidget>
#include <QPushButton>
#include <QLabel>
#include <QVBoxLayout>
#include <QFileDialog>
#include <QDir>
#include <QFile>
#include <QTextStream>
#include <QMessageBox>
#include <QProgressBar>
#include <QFileInfo>
#include <QtConcurrent/QtConcurrent>
#include <xlsxdocument.h>
#include <xlsxcellrange.h>

class ExcelToCsvConverter : public QWidget {
    Q_OBJECT
public:
    explicit ExcelToCsvConverter(QWidget* parent = nullptr) : QWidget(parent) {
        setupUi();
        connect(selectBtn, &QPushButton::clicked, this, &ExcelToCsvConverter::selectDirectory);
        connect(convertBtn, &QPushButton::clicked, this, &ExcelToCsvConverter::startConversion);
        convertBtn->setEnabled(false);
    }

private slots:
    void selectDirectory() {
        QString dir = QFileDialog::getExistingDirectory(this, "Select Directory Containing Excel Files");
        if (dir.isEmpty()) return;
        selectedDir = dir;
        dirLabel->setText("Selected: " + dir);
        convertBtn->setEnabled(true);
    }

    void startConversion() {
        if (selectedDir.isEmpty()) return;

        QDir dir(selectedDir);
        QStringList filters = {"*.xlsx"}; // QXlsx supports .xlsx (Office 2007+)
        QStringList excelFiles = dir.entryList(filters, QDir::Files | QDir::Readable);

        if (excelFiles.isEmpty()) {
            QMessageBox::information(this, "Info", "No .xlsx files found in the selected directory.");
            return;
        }

        QString outputDirPath = selectedDir + "/csv_output";
        if (!QDir().mkpath(outputDirPath)) {
            QMessageBox::critical(this, "Error", "Failed to create output directory: " + outputDirPath);
            return;
        }

        // Disable UI during conversion
        convertBtn->setEnabled(false);
        selectBtn->setEnabled(false);
        progressBar->setRange(0, excelFiles.size());
        progressBar->setValue(0);
        statusLabel->setText("Converting...");

        // Run conversion in background thread to keep GUI responsive
        QtConcurrent::run([this, excelFiles, dir, outputDirPath]() {
            int successCount = 0;
            for (int i = 0; i < excelFiles.size(); ++i) {
                QString xlsxPath = dir.absoluteFilePath(excelFiles[i]);
                QString baseName = QFileInfo(excelFiles[i]).completeBaseName();
                QString csvPath = outputDirPath + "/" + baseName + ".csv";

                bool ok = convertXlsxToCsv(xlsxPath, csvPath);
                if (ok) successCount++;

                // Update progress on GUI thread
                QMetaObject::invokeMethod(this, [this, i, excelFiles, ok, successCount]() {
                    progressBar->setValue(i + 1);
                    if (!ok) statusLabel->setText("Failed: " + excelFiles[i]);
                    else statusLabel->setText(QString("Converted %1/%2").arg(i + 1).arg(excelFiles.size()));
                }, Qt::QueuedConnection);
            }

            // Re-enable UI and show result on GUI thread
            QMetaObject::invokeMethod(this, [this, successCount, excelFiles, outputDirPath]() {
                convertBtn->setEnabled(true);
                selectBtn->setEnabled(true);
                statusLabel->setText("Done!");
                QMessageBox::information(this, "Conversion Complete",
                    QString("Successfully converted %1/%2 files.\nOutput folder:\n%3")
                    .arg(successCount).arg(excelFiles.size()).arg(outputDirPath));
            }, Qt::QueuedConnection);
        });
    }

private:
    bool convertXlsxToCsv(const QString& xlsxPath, const QString& csvPath) {
        QXlsx::Document xlsx(xlsxPath);
        if (xlsx.sheetNames().isEmpty()) return false;

        // Convert first sheet only (modify loop to handle all sheets if needed)
        xlsx.selectSheet(xlsx.sheetNames().first());
        QXlsx::CellRange range = xlsx.dimension();

        QFile csvFile(csvPath);
        if (!csvFile.open(QIODevice::WriteOnly | QIODevice::Text)) return false;
        QTextStream out(&csvFile);
        out.setCodec("UTF-8");

        // If sheet is empty, just create empty CSV
        if (!range.isValid()) {
            csvFile.close();
            return true;
        }

        for (int row = range.firstRow(); row <= range.lastRow(); ++row) {
            QStringList line;
            for (int col = range.firstColumn(); col <= range.lastColumn(); ++col) {
                QXlsx::Cell* cell = xlsx.cellAt(row, col);
                QString val = cell ? cell->value().toString() : "";

                // RFC 4180 CSV escaping
                if (val.contains(',') || val.contains('"') || val.contains('\n') || val.contains('\r')) {
                    val.replace('"', "\"\"");
                    val = "\"" + val + "\"";
                }
                line << val;
            }
            out << line.join(',') << "\n";
        }

        csvFile.close();
        return true;
    }

    void setupUi() {
        auto* layout = new QVBoxLayout(this);
        selectBtn = new QPushButton("Select Directory", this);
        convertBtn = new QPushButton("Convert to CSV", this);
        dirLabel = new QLabel("No directory selected", this);
        statusLabel = new QLabel("Ready", this);
        progressBar = new QProgressBar(this);
        progressBar->setValue(0);

        layout->addWidget(selectBtn);
        layout->addWidget(convertBtn);
        layout->addWidget(dirLabel);
        layout->addWidget(progressBar);
        layout->addWidget(statusLabel);
        layout->addStretch();
        setLayout(layout);
        setWindowTitle("Excel to CSV Converter");
        resize(450, 280);
    }

    QPushButton* selectBtn = nullptr;
    QPushButton* convertBtn = nullptr;
    QLabel* dirLabel = nullptr;
    QLabel* statusLabel = nullptr;
    QProgressBar* progressBar = nullptr;
    QString selectedDir;
};

#include "main.moc"

int main(int argc, char* argv[]) {
    QApplication app(argc, argv);
    app.setStyle("Fusion"); // Cross-platform consistent look
    ExcelToCsvConverter converter;
    converter.show();
    return app.exec();
}
```

### 📌 Important Notes

